const description: { en: string; ja: string } = {"en":"Two wisteria sprays hang from rounded leaves. Below the calyx, a narrow-waisted bar flares to rounded ends.","ja":"丸みのある葉から二つの藤の花房が垂れます。萼の下には、中央がくびれ、両端が丸く広がる棒を置きます。"};

export default construction;
